LOGIC_BY_ID: Dict[str, Dict[str, Any]] = {item["id"]: item for item in LOGIC_MATH_DATA}
LOGIC_BY_SUBMODE: Dict[str, List[Dict[str, Any]]] = {}
for item in LOGIC_MATH_DATA:
    LOGIC_BY_SUBMODE.setdefault(item["sub_mode"], []).append(item)


def get_logic_item_by_id(item_id: str) -> Optional[Dict[str, Any]]:
    """Retrieve a logic/math item by its unique ID."""
    return LOGIC_BY_ID.get(item_id)


def get_logic_items_by_submode(sub_mode: str) -> List[Dict[str, Any]]:
    """Retrieve all logic/math items for a specific sub-mode."""
    return LOGIC_BY_SUBMODE.get(sub_mode, [])


def get_random_logic_item(sub_mode: Optional[str] = None) -> Dict[str, Any]:
    """Get a random logic item, optionally filtered by sub-mode."""
    if sub_mode and sub_mode in LOGIC_BY_SUBMODE:
        return random.choice(LOGIC_BY_SUBMODE[sub_mode])
    return random.choice(LOGIC_MATH_DATA)
